public class CalculadoraCientifica {
    public static double suma(double a, double b) { return a + b; }
    public static double resta(double a, double b) { return a - b; }
    public static double multiplicacion(double a, double b) { return a * b; }
    public static double division(double a, double b) {
        if (b == 0) throw new ArithmeticException("No se puede dividir por cero");
        return a / b;
    }
    public static double potencia(double base, double exponente) {
        return Math.pow(base, exponente);
    }
    public static double raizCuadrada(double numero) {
        if (numero < 0) throw new IllegalArgumentException("No se puede calcular raíz cuadrada de número negativo: " + numero);
        return Math.sqrt(numero);
    }

    public static void main(String[] args) {
        int total = 0, pasados = 0, fallidos = 0;
        double epsilon = 0.0001;

        // Tests de suma
        total++;
        if (Math.abs(suma(2.5, 3.5) - 6.0) < epsilon) { System.out.println("PASS: suma(2.5, 3.5) = 6.0"); pasados++; }
        else { System.out.println("FAIL: suma(2.5, 3.5) esperado 6.0"); fallidos++; }

        total++;
        if (Math.abs(suma(0, 0) - 0) < epsilon) { System.out.println("PASS: suma(0, 0) = 0"); pasados++; }
        else { System.out.println("FAIL: suma(0, 0) esperado 0"); fallidos++; }

        total++;
        if (Math.abs(suma(-5, 5) - 0) < epsilon) { System.out.println("PASS: suma(-5, 5) = 0"); pasados++; }
        else { System.out.println("FAIL: suma(-5, 5) esperado 0"); fallidos++; }

        // Tests de resta
        total++;
        if (Math.abs(resta(10, 3) - 7) < epsilon) { System.out.println("PASS: resta(10, 3) = 7"); pasados++; }
        else { System.out.println("FAIL: resta(10, 3) esperado 7"); fallidos++; }

        total++;
        if (Math.abs(resta(0, 5) - (-5)) < epsilon) { System.out.println("PASS: resta(0, 5) = -5"); pasados++; }
        else { System.out.println("FAIL: resta(0, 5) esperado -5"); fallidos++; }

        // Tests de multiplicación
        total++;
        if (Math.abs(multiplicacion(3, 4) - 12) < epsilon) { System.out.println("PASS: multiplicacion(3, 4) = 12"); pasados++; }
        else { System.out.println("FAIL: multiplicacion(3, 4) esperado 12"); fallidos++; }

        total++;
        if (Math.abs(multiplicacion(0, 1000) - 0) < epsilon) { System.out.println("PASS: multiplicacion(0, 1000) = 0"); pasados++; }
        else { System.out.println("FAIL: multiplicacion(0, 1000) esperado 0"); fallidos++; }

        total++;
        if (Math.abs(multiplicacion(-3, -3) - 9) < epsilon) { System.out.println("PASS: multiplicacion(-3, -3) = 9"); pasados++; }
        else { System.out.println("FAIL: multiplicacion(-3, -3) esperado 9"); fallidos++; }

        // Tests de división
        total++;
        if (Math.abs(division(10, 2) - 5) < epsilon) { System.out.println("PASS: division(10, 2) = 5"); pasados++; }
        else { System.out.println("FAIL: division(10, 2) esperado 5"); fallidos++; }

        total++;
        if (Math.abs(division(7, 2) - 3.5) < epsilon) { System.out.println("PASS: division(7, 2) = 3.5"); pasados++; }
        else { System.out.println("FAIL: division(7, 2) esperado 3.5"); fallidos++; }

        total++;
        try {
            division(5, 0);
            System.out.println("FAIL: division(5,0) debió lanzar excepción"); fallidos++;
        } catch (ArithmeticException e) {
            System.out.println("PASS: division(5, 0) lanza ArithmeticException"); pasados++;
        }

        // Tests de potencia
        total++;
        if (Math.abs(potencia(2, 3) - 8) < epsilon) { System.out.println("PASS: potencia(2, 3) = 8"); pasados++; }
        else { System.out.println("FAIL: potencia(2, 3) esperado 8"); fallidos++; }

        total++;
        if (Math.abs(potencia(5, 0) - 1) < epsilon) { System.out.println("PASS: potencia(5, 0) = 1"); pasados++; }
        else { System.out.println("FAIL: potencia(5, 0) esperado 1"); fallidos++; }

        total++;
        if (Math.abs(potencia(2, -1) - 0.5) < epsilon) { System.out.println("PASS: potencia(2, -1) = 0.5"); pasados++; }
        else { System.out.println("FAIL: potencia(2, -1) esperado 0.5"); fallidos++; }

        // Tests de raíz cuadrada
        total++;
        if (Math.abs(raizCuadrada(9) - 3) < epsilon) { System.out.println("PASS: raizCuadrada(9) = 3"); pasados++; }
        else { System.out.println("FAIL: raizCuadrada(9) esperado 3"); fallidos++; }

        total++;
        if (Math.abs(raizCuadrada(0) - 0) < epsilon) { System.out.println("PASS: raizCuadrada(0) = 0"); pasados++; }
        else { System.out.println("FAIL: raizCuadrada(0) esperado 0"); fallidos++; }

        total++;
        if (Math.abs(raizCuadrada(2) - 1.4142) < 0.01) { System.out.println("PASS: raizCuadrada(2) ~ 1.4142"); pasados++; }
        else { System.out.println("FAIL: raizCuadrada(2) esperado ~1.4142"); fallidos++; }

        total++;
        try {
            raizCuadrada(-4);
            System.out.println("FAIL: raizCuadrada(-4) debió lanzar excepción"); fallidos++;
        } catch (IllegalArgumentException e) {
            System.out.println("PASS: raizCuadrada(-4) lanza IllegalArgumentException"); pasados++;
        }

        // Reporte final
        System.out.println("==================================");
        System.out.println("REPORTE DE TESTS");
        System.out.println("Total: " + total);
        System.out.println("Pasados: " + pasados);
        System.out.println("Fallidos: " + fallidos);
        System.out.println("Tasa de éxito: " + (pasados * 100 / total) + "%");
        System.out.println("==================================");
    }
}
